/* Overview, service report, batched receipts and hands-free review. */
I.repeat='M3 10a9 9 0 0 1 15-6l3 3M21 2v5h-5M21 14a9 9 0 0 1-15 6l-3-3M3 22v-5h5';
I.once='M5 4h14v16H5zM9 9h6M9 13h4';
I.draft='M5 3h10l4 4v14H5zM9 11h6M9 15h4';
const v6Home=home, v6Process=processInput, v6Revision=initRevision;
const CARE=[
 {id:'care_food',title:'小包的辅食灵感',theme:'小包成长',why:'你在给小包准备食材，我可以把适龄搭配一起整理好。',plan:'确认月龄与过敏情况，整理三天搭配和备餐清单。',question:'小包现在几个月大？有没有已知食物过敏？'},
 {id:'care_return',title:'替你留意退货期限',theme:'生活照料',why:'最近在挑家电，容易忙过了试用与退货时间。',plan:'先请你提供订单，再整理退货期限，提前一天提醒。',question:'请提供要跟进的订单与签收日期。',periodic:true},
 {id:'care_trip',title:'周末出行前的小检查',theme:'家人出行',why:'家人周末要出行，可以提前备好证件与行李清单。',plan:'结合已确认行程整理清单，出发前提醒你检查。'}
];
function initOverview(){
 S.topicOpen ||= {}; S.careAccepted ||= {}; S.careSelected ||= []; S.drafts ||= [];
 if(S.proposal==='accepted'&&item('food')) S.careAccepted.care_food='food';
 if(!S.v7){
  // Start timestamps are independent of deadlines. Never infer them from due.
  const starts={shop:'2026-10-14T09:00',pickup:'2026-10-13T15:20',meeting:'2026-10-13T14:00',menu:'2026-10-13T09:00',pdf_sample:'2026-10-13T10:00'};
  S.items.forEach(t=>{if(starts[t.id])t.startedAt=starts[t.id];});
  S.instances.forEach(t=>{t.scheduledStart=t.due;});
  if(now().getTime()<ts('2026-10-14T09:10')){S.demoTime='2026-10-14T09:10:00+08:00';S.wallStart=Date.now();}
  S.v7=true;
 }
}
initRevision=function(){v6Revision();initOverview();};
function needUser(t){return t.status==='wait_user'||(t.status==='error'&&t.userRequired!==false)||(t.confirmations||[]).some(q=>!q.answer);}
function groupStats(list){return {ai:list.filter(t=>!terminal(t.status)&&!needUser(t)&&t.status!=='paused').length,you:list.filter(needUser).length,archive:list.filter(t=>terminal(t.status)&&t.archive!=='archived'&&!needUser(t)).length,paused:list.filter(t=>t.status==='paused').length};}
function frequency(t){const p=t.parent?parentOf(t):t;return `<span class="tiny-icon" title="${p.kind==='continuing'?'周期 / 持续任务':'一次性任务'}" aria-label="${p.kind==='continuing'?'周期或持续任务':'一次性任务'}">${icon(p.kind==='continuing'?'repeat':'once')}</span>${t.person?`<span class="tiny-icon" title="需要本人线下参与" aria-label="需要本人参与">${icon('person')}</span>`:''}`;}
function latestLine(t){const question=(t.confirmations||[]).find(q=>!q.answer);return question?question.question:(terminal(t.status)?t.result||t.summary:t.summary||t.plan)||'已接下需求，正在整理执行思路。';}
function receiptState(t){return t.receiptAction==='创建'?'created':t.status||'todo';}
function receiptLabel(t){return receiptState(t)==='created'?'已创建':STATUS[t.status]||'待启动';}
function unifiedTaskCard(t,tile=false){const state=receiptState(t),p=t.parent?parentOf(t):t;return `<button class="unified-task-card ${tile?'batch-tile':'receipt-card dense-card'}" data-state="${state}" ${t.storyKey?`data-story-state="${t.storyKey}"`:''} data-task="${t.id}" onclick="detail('${t.id}')"><div class="unified-title"><strong>${esc(t.title)}</strong><span class="unified-status">${esc(receiptLabel(t))}</span></div><p>${esc(t.plan||latestLine(t))}</p><div class="unified-meta"><span>${esc(t.theme||p?.theme||'生活照料')}</span>${frequency(t)}</div><div class="unified-footer"><span>${esc(t.receiptTime|| (t.created?fmt(t.created):''))}</span><span>查看详情 ↗</span></div></button>`;}
compactCard=function(t){return unifiedTaskCard(t);};
function overviewCard(t){return compactCard({...t,plan:latestLine(t)});}
function batchCards(cards){const c=(cards||[]).filter(Boolean);if(!c.length)return '';if(c.length===1)return compactCard(c[0]);const needs=c.filter(needUser).length,done=c.filter(t=>t.status==='done').length;const preview=c.slice(0,2).map(t=>t.title).join('、');return `<details class="batch-bundle" data-batch="${esc(c.map(t=>t.id).join('|'))}" open><summary><div class="batch-heading"><span class="batch-stack">${icon('report')}</span><strong>本次任务更新 <em>${c.length} 项</em></strong><span class="batch-toggle"><span class="when-closed">展开</span><span class="when-open">收起</span><i>⌄</i></span></div><div class="batch-overview">${needs?`<span>${needs} 项待您处理</span>`:''}${done?`<span>${done} 项已完成</span>`:''}${!needs&&!done?'<span>已为您整理好最新进展</span>':''}</div><p class="batch-preview">${esc(preview)}${c.length>2?` 等 ${c.length} 项`:''}</p></summary><div class="batch-grid">${c.map(t=>unifiedTaskCard(t,true)).join('')}</div></details>`;}

function snapshot(t){return JSON.parse(JSON.stringify({...t,theme:parentOf(t).theme,plan:latestLine(t)}));}
home=function(){const old=S.messages;S.messages=old.filter(m=>m.kind!=='batch_v7');let h=v6Home();S.messages=old;
 // Preserve chronological placement of all receipts, including older formats.
 const boundary=h.indexOf('<div class="quick-examples">');
 
 // Reuse intro/example from v6; regenerate the message tail in original order.
 const prefix=v6HomePrefix();
 return prefix+old.filter(m=>!m.supersededShoppingExample).map(m=>{if(m.kind==='batch_v7')return `${m.input?`<div class="user-msg">${esc(m.input)}</div>`:''}${assistant(`<div class="receipt-caption">${esc(m.action)} · ${fmt(m.at)}</div><p>${esc(m.text)}</p>${batchCards(m.cards)}`)}`;const t=m.snapshot||entity(m.id);return `${m.input?`<div class="user-msg">${esc(m.input)}</div>`:''}${assistant(`${m.action==='完成'&&t?requestQuote(t):''}<p>${esc(m.text||'')}</p>${m.kind==='task_receipt'&&t?compactCard({...t,receiptAction:m.action}):batchCards((m.ids||[]).map(entity))}`)}`;}).join('')+h.slice(boundary);
};
function v6HomePrefix(){return `${assistant('<p>有什么事，直接吩咐我就好。</p>')}<div class="user-msg">家里牛奶和小包吃的菜没有了，参考常买的帮我加购，优惠帮我用上。</div>${assistant('<p>收到，已为你建好「给小包买菜」。我先整理常购清单、核对优惠，加购后待您下单支付。</p>'+compactCard(S.initialReceipt||item('shop')))}<div class="user-msg">你可以同时帮我处理别的事吗？</div>${assistant('<p>可以，这件事会继续推进。你直接说下一件就好，有进展我再回来告诉你。</p>')}`;}
const HISTORY=[['日常采购',18,216,96],['退货跟进',2,30,0],['预订车票',3,60,90],['重要提醒',14,42,0],['长期照料',5,150,0]];
function serviceTotals(){const rows=HISTORY.map(r=>[...r]);if(item('shop')?.status==='done')rows[0][1]++;rows[4][1]+=S.items.filter(t=>t.kind==='continuing'&&t.status!=='cancelled').length;return rows;}
function impact(){const done=S.items.filter(t=>t.status==='done'&&t.closeReason!=='auto'),days=Math.max(1,Math.floor((now().getTime()-ts('2026-09-12T00:00'))/86400000)+1);return {days,total:42+S.items.length,hours:(HISTORY.reduce((a,r)=>a+r[2],0)/60).toFixed(1),money:186,done:42+done.length};}
function serviceReport(){const n=impact();sheet('这些日子，帮你省了些心',`<div class="report-date">9 月 12 日至 ${fmt(now().toISOString()).slice(0,5)} · 演示服务报告</div><h2>陪伴 ${n.days} 天，<br>把时间留给生活。</h2><p class="small muted">累计接下 ${n.total} 项任务；${n.done} 项已有完成记录。未核实的自动关闭不计入办成数。</p><div class="report-benefits"><div><strong>${n.hours}<small> 小时</small></strong>估算节约用时</div><div><strong>¥${n.money}</strong>已核对优惠示例</div></div><h3>做过哪些事</h3><div class="report-ledger">${serviceTotals().map(r=>`<div><span>${r[0]}<small>${r[2]} 分钟估算 · ${r[3]?'示例优惠 ¥'+r[3]:'不计节省金额'}</small></span><strong>${r[1]} ${r[0]==='长期照料'?'项':'次'}</strong></div>`).join('')}</div><h3>关于你的小观察</h3><p class="report-insight">${S.items.filter(t=>t.theme==='家庭餐桌').length} 项任务与家庭餐桌有关。你更在意常购规格、孩子口味与省心补货，可以把“缺什么”集中交代，搭配菜单一起准备。</p><h3>接下来可以这样安排</h3><p class="report-insight">家人出行和本人参与的事项优先过一遍；比价、项目晨报继续交给我。辅食建议采纳后，先核对月龄与过敏信息。</p><h3>别漏了</h3><p class="report-insight">当前 ${S.items.filter(t=>t.archive!=='archived'&&needUser(t)).length} 项需要你答复或接手。${pending().length} 条已结束记录可以一起归档。</p><details class="report-method"><summary>数字怎么算 · 查看统计依据</summary><p>以上历史为内置模拟汇总：18 次采购、2 次退货、3 次订票、14 次提醒、5 项长期任务，共 42 项；不代表真实订单或已接入账号。分类次数另计当前已完成的加购，以及当前未取消的长期主体。</p><p>省时 = 各类服务的模拟人工基准分钟数之和 ÷ 60（共 498 分钟）。不使用 AI 运行时长，也不把周期子步骤重复累计。当前任务尚无人工耗时基准，暂不计入省时。</p><p>省钱 = 采购优惠 96 元 + 订票优惠 90 元。真实产品只计有同规格、同条件比较基准与成交凭证的差额，退款不算省钱，未支付的购物车优惠不算已省。没有依据时显示“待核实”。</p><p>累计任务按主体去重，未来实例不重复计数。正式统计应支持下钻至每笔服务记录；本 Demo 仅提供上述历史汇总样例。</p></details>`);}
function priorityTasks(){return S.items.filter(t=>t.archive!=='archived'&&(needUser(t)||t.priority==='high')).sort((a,b)=>(b.status==='error')-(a.status==='error')||(ts(a.due)||Infinity)-(ts(b.due)||Infinity)).slice(0,3);}
overview=function(){initOverview();const all=S.items.filter(t=>t.archive!=='archived'),g=groupStats(all),n=impact(),ongoing=all.filter(t=>!terminal(t.status)||needUser(t)).length;return `<div class="overview-intro"><div class="eyebrow">YOUR EVERYDAY ALLY</div><h1>日子里的小事，<br>我都放在心上。</h1></div><section class="life-impact"><div class="impact-top">陪伴您 <b>${n.days}</b> 天 <span>演示数据</span></div><p>累计为您照料 <b>${n.total}</b> 项事</p><div class="impact-numbers"><div><strong>${n.hours}<small> 小时</small></strong><span>预估省下时间</span></div><div><strong>${n.money}<small> 元</small></strong><span>省下的花费 · 示例</span></div></div><p class="life-counts">采购 <b>${serviceTotals()[0][1]}</b> 次 · 退货 <b>2</b> 次 · 订票 <b>3</b> 次<br>重要提醒 <b>14</b> 次 · 长期陪伴 <b>${serviceTotals()[4][1]}</b> 项</p><button class="impact-report" onclick="serviceReport()">看看这段时间的照料报告 <span>↗</span></button></section><section class="now-overview"><h2>正在为您照看 <b>${ongoing}</b> 项事</h2><p>其中 <strong>${g.you} 件待您处理</strong>${g.archive?` · ${g.archive} 件等归档`:''}</p>${priorityTasks().length?`<div class="priority-list"><div class="priority-caption">这几件，先和您说</div>${priorityTasks().map((t,i)=>`<button onclick="detail('${t.id}')"><span class="priority-num">${i+1}</span><span><strong>${esc(t.title)}</strong><small>${esc(latestLine(t))}</small></span><span>↗</span></button>`).join('')}</div>`:''}</section><div class="tabs5"><button class="${S.view!=='timeline'?'active':''}" onclick="S.view='progress';save();render()">按主题看</button><button class="${S.view==='timeline'?'active':''}" onclick="S.view='timeline';save();render()">时间轴</button><button onclick="iconHelp()" class="help-link">图标说明</button></div>${S.showArchived?'<div class="inline-notice">历史归档 <button onclick="S.showArchived=false;render()">返回当前</button></div>':''}${S.view==='timeline'?timeline(filtered()):progress(liveItems())}<div class="overview-bottom"><button onclick="archiveReview()">一起归档 · ${pending().length}</button><button onclick="showArchives()">历史记录 ↗</button></div><p class="notice">演示原型 · 购物、提醒与服务统计均为模拟</p>`;};
function foldCounts(list){const g=groupStats(list);return `<span>${g.ai} AI 在管</span><span class="${g.you?'amber':''}">${g.you} 待您处理</span><span>${g.archive} 待归档</span>${g.paused?`<span>${g.paused} 已暂停</span>`:''}`;}
progress=function(list){const topics=[...new Set([...S.topics,...list.map(t=>t.theme)])],openAll=topics.every(t=>S.topicOpen[t])&&S.topicOpen.care;return `<div class="group-tools"><span>按主题，整体过一遍</span><button onclick="toggleAllTopics()">${openAll?'全部收起':'全部展开'}</button></div>${S.showArchived?'':careGroup()}${topics.map((theme,i)=>{const tasks=list.filter(t=>t.theme===theme).sort((a,b)=>Number(needUser(b))-Number(needUser(a))||(ts(b.created)||0)-(ts(a.created)||0));if(!tasks.length)return '';return `<details class="topic-fold" ${S.topicOpen[theme]?'open':''} ontoggle="rememberFold('${encodeURIComponent(theme)}',this.open)"><summary><div class="topic-fold-title"><strong>${esc(theme)}</strong><span>${tasks.length} 件 <i>⌄</i></span></div><div class="fold-counts">${foldCounts(tasks)}</div></summary><div class="topic-content">${tasks.map(t=>overviewCard(t)+(!t.parent&&t.kind==='continuing'&&nextInstance(t.id)?`<button class="next-compact" onclick="detail('${nextInstance(t.id).id}')">${icon('repeat')}<span>下次 ${fmt(nextInstance(t.id).scheduledStart||nextInstance(t.id).due)}</span>${badge(nextInstance(t.id))}</button>`:'')).join('')}</div></details>`;}).join('')}`;};
function rememberFold(key,open){S.topicOpen[decodeURIComponent(key)]=open;save();}
function toggleAllTopics(){const topics=[...new Set([...S.topics,...S.items.map(t=>t.theme),'care'])],open=!topics.every(t=>S.topicOpen[t]);topics.forEach(t=>S.topicOpen[t]=open);save();render();}
function careGroup(){const accepted=CARE.filter(c=>S.careAccepted[c.id]).length;return `<details class="topic-fold care-fold" ${S.topicOpen.care?'open':''} ontoggle="rememberFold('care',this.open)"><summary><div class="topic-fold-title"><strong>✧ 主动关怀</strong><span>${CARE.length} 个建议 <i>⌄</i></span></div><div class="fold-counts"><span>结合您的近况，多想一步</span><span>${accepted} 已采纳</span></div></summary><div class="topic-content"><p class="care-note">选您需要的；采纳后，我才开始办。</p>${CARE.map(c=>{const id=S.careAccepted[c.id];return `<label class="care-option"><input type="checkbox" ${id?'disabled checked':S.careSelected.includes(c.id)?'checked':''} onchange="selectCare('${c.id}',this.checked)"><span><strong>${esc(c.title)}</strong><small>${esc(c.why)}</small><em>${id?'已采纳 · 已加入'+c.theme:c.plan}</em></span></label>${id?`<button class="care-task-link" onclick="detail('${id}')">查看已采纳任务 ↗</button>`:''}`;}).join('')}<div class="care-actions"><button class="secondary" onclick="acceptCare(true)" ${accepted===CARE.length?'disabled':''}>全部采纳</button><button class="primary" id="adopt-selected" onclick="acceptCare(false)" ${!S.careSelected.length?'disabled':''}>采纳所选${S.careSelected.length?' · '+S.careSelected.length:''}</button></div></div></details>`;}
function selectCare(id,checked){S.careSelected=S.careSelected.filter(x=>x!==id);if(checked&&!S.careAccepted[id])S.careSelected.push(id);save();const b=document.getElementById('adopt-selected');b.disabled=!S.careSelected.length;b.textContent='采纳所选'+(S.careSelected.length?' · '+S.careSelected.length:'');}
function acceptCare(all){const selected=CARE.filter(c=>!S.careAccepted[c.id]&&(all||S.careSelected.includes(c.id)));if(!selected.length)return;const at=now().toISOString();const cards=selected.map(c=>{const id=c.id;const t={id,title:c.title,theme:c.theme,kind:c.periodic?'continuing':'oneoff',subtype:c.periodic?'监控':'',status:c.question?'wait_user':'running',source:'ai',consent:at,created:at,quote:'您已采纳推荐任务：'+c.title,summary:c.question||'正在根据已确认的行程整理清单。',plan:c.plan,result:'',confirmations:c.question?[{id:'care_info',question:c.question,at,blocking:true,options:['补充资料','暂缓这项任务']}]:[],steps:[{title:'核对相关信息',status:c.question?'wait_user':'running',summary:c.question||c.plan,at:fmt(at)},{title:'整理方案并向您汇报',status:'todo',summary:c.plan}]};S.items.push(t);S.careAccepted[c.id]=id;return snapshot(t);});S.messages.push({kind:'batch_v7',action:'采纳推荐',input:'您已采纳推荐任务：'+selected.map(c=>c.title).join('、'),text:'收到，正在为您处理。已将 '+cards.length+' 项关怀加入对应主题，需要补充的资料会在任务里集中列出。',cards,at});S.careSelected=[];save();render();toast('已采纳 '+cards.length+' 项，并合并发到主会话。');}
function iconHelp(){sheet('图标与计数说明',`<div class="icon-guide"><p>${icon('once')} 一次性任务</p><p>${icon('repeat')} 周期、监控或持续任务；时间轴显示本次实例</p><p>${icon('person')} 需要您本人线下参与，AI 负责准备和提醒</p></div><p class="small muted">卡片上的状态描述任务目标；主题上的数字描述谁来接着办。暂停单列，AI 在管不含已暂停。</p><p class="small muted">已完成的加购仍可能需要您支付：只提示“待您处理”，不把任务改回运行中。确认支付或暂不购买后再进入待归档。</p><div class="symbol-legend"><span>✓ 步骤完成</span><span>— 步骤进行</span><span>○ 步骤待开始</span></div>`);}
function startAt(t){return t.startedAt||t.scheduledStart||null;}
function startDate(t){return startAt(t)?new Date(ts(startAt(t))+8*3600000).toISOString().slice(0,10):null;}
function startPart(t){const h=new Date(ts(startAt(t))+8*3600000).getUTCHours();return h<12?0:h<18?1:2;}
timelineDates=function(){const today=new Date(now().getTime()+8*3600000).toISOString().slice(0,10);let start=Date.parse(today+'T12:00Z'),len=1;if(S.range==='three'){start-=86400000;len=3}else if(S.range==='week'){start-=3*86400000;len=7}else if(S.range==='all'){const ds=timelineEntries(filtered()).map(startDate).filter(Boolean).sort();start=Date.parse((ds[0]||today)+'T12:00Z');len=Math.round((Date.parse((ds.at(-1)||today)+'T12:00Z')-start)/86400000)+1;}return Array.from({length:len},(_,i)=>new Date(start+i*86400000).toISOString().slice(0,10));};
timeline=function(list){const dates=timelineDates(),events=timelineEntries(list);let html=`<div class="timehead">时段</div>${dates.map(d=>`<div class="timehead">${d.slice(5,7)}月<strong>${d.slice(-2)}</strong></div>`).join('')}`;['上午','下午','晚上'].forEach((label,p)=>{html+=`<div class="daypart">${label}</div>`;dates.forEach(d=>{const tasks=events.filter(t=>startDate(t)===d&&startPart(t)===p).sort((a,b)=>ts(startAt(a))-ts(startAt(b)));html+=`<div class="timecell">${tasks.map(t=>`<button class="timeitem ${t.status}" onclick="detail('${t.id}')"><small>${fmt(startAt(t)).slice(-5)} ${t.startedAt?'启动':'预计启动'}</small><strong>${esc(t.title)}</strong><div>${frequency(t)}</div><small>${STATUS[t.status]}</small></button>`).join('')||'<span class="muted small">—</span>'}</div>`;});});return `<div class="filters">${['全部',...S.topics].map(n=>`<button class="${S.themeFilter===n?'active':''}" onclick="setTheme(${esc(JSON.stringify(n))})">${esc(n)}</button>`).join('')}</div><div class="date-range">${[['all','全部'],['today','今天'],['three','近三天'],['week','近一周']].map(([k,l])=>`<button class="${S.range===k?'active':''}" onclick="S.range='${k}';save();render()">${l}</button>`).join('')}</div><div class="timepanel"><div class="timebar"><span>任务启动时间 · 可横向滑动</span><span><button onclick="zoom(-1)" aria-label="缩小">−</button><button onclick="zoom(1)" aria-label="放大">＋</button></span></div><div class="timeline-scroll" tabindex="0" aria-label="可横向及纵向滚动的任务时间轴"><div class="timegrid" style="--n:${dates.length};--cw:${dates.length>3?'88px':'104px'}">${html}</div></div></div><div class="timeline-key">${icon('once')} 一次性 ${icon('repeat')} 周期 / 持续 ${icon('person')} 本人参与</div><p class="clocknote">${dates[0]} — ${dates.at(-1)}<br>近三天：昨天、今天、明天。按实际／预计启动时间定位，不用截止时间代替。</p><details class="topic-fold"><summary>启动时间待明确 · ${events.filter(t=>!startAt(t)).length} 项 <span>⌄</span></summary><div class="topic-content">${events.filter(t=>!startAt(t)).map(overviewCard).join('')}</div></details>`;};
// Batch parsing is intentionally local demo logic, with an editable confirmation step.
let batchSeq=0;
processInput=function(text,context=''){const existingIds=new Set(S.items.map(t=>t.id));const before=S.messages.length,ids=[],clauses=text.split(/[；;\n]+/).map(x=>x.trim()).filter(Boolean);for(const clause of clauses){let got;if(context&&context.startsWith('care_')&&entity(context)){const t=entity(context);t.updates=[...(t.updates||[]),{text:clause,at:now().toISOString()}];got=[context];}else got=v6Process(clause,context);ids.push(...got);for(const id of got){const t=entity(id);if(!t.startedAt&&t.status==='running')t.startedAt=now().toISOString();if(id==='pickup'&&/餐厅|订餐/.test(clause)&&/先别|先不|不要|取消/.test(clause)){t.constraints=[...(t.constraints||[]),{text:clause,at:now().toISOString()}];t.summary='餐厅暂不预订；接站与停车安排继续保留。';}else if(/暂停|先别|先不/.test(clause)){t.beforePause=t.status;t.status='paused';t.result='已收到您的暂停安排，已有记录保留，后续暂不执行。';t.summary=t.result;S.instances.filter(x=>x.parent===id&&!terminal(x.status)).forEach(x=>{x.beforePause=x.status;x.status='paused';});}else if(/取消/.test(clause)){t.status='cancelled';t.archive='pending';t.result='已按您的要求取消，已有记录保留。';S.instances.filter(x=>x.parent===id&&!terminal(x.status)).forEach(x=>{x.status='cancelled';x.archive='pending';});}else if(t.status==='wait_user'&&t.confirmations?.some(q=>!q.answer)&&!(/暂停|取消/.test(clause))){t.summary='已收到补充：“'+clause+'”。我先核对是否足以继续，确认记录中保留原问题。';}else if(!terminal(t.status)&&t.status!=='paused'){t.summary='已记录：“'+clause+'”。正在核对并按补充继续处理。';}}}
const unique=[...new Set(ids)];if(unique.length){S.messages.splice(before);S.messages.push({kind:'batch_v7',action:'批量安排',input:text,text:'收到，正在为您处理。'+(unique.length>1?'这 '+unique.length+' 项已集中更新，进展会继续汇报。':'已接到对应任务，后续进展继续向您汇报。'),cards:unique.map(id=>({...snapshot(entity(id)),receiptAction:!existingIds.has(id)&&['running','todo'].includes(entity(id).status)?'创建':'更新'})),at:now().toISOString()});}save();return unique;};
// New task ids remain unique when multiple clauses arrive in the same millisecond.

function prepareRows(text){return text.split(/[；;\n]+/).map(s=>s.trim()).filter(Boolean).map(s=>({text:s,context:voiceContext||'',id:'line_'+(++batchSeq)}));}
let listening=false,voiceManual=false,voiceRows=[],voiceElapsed=0,voiceTick=null,silenceTimer=null,voiceStream=null,voiceAudio=null,voiceRAF=null,activeDraft='',voiceBase='',voiceError=false;
function armSilence(){clearTimeout(silenceTimer);silenceTimer=setTimeout(()=>finishListening(),60000);}
async function monitorSilence(){try{if(!navigator.mediaDevices?.getUserMedia)return;voiceStream=await navigator.mediaDevices.getUserMedia({audio:true});if(!listening){voiceStream.getTracks().forEach(t=>t.stop());return;}const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;voiceAudio=new AC();const analyser=voiceAudio.createAnalyser();voiceAudio.createMediaStreamSource(voiceStream).connect(analyser);const data=new Uint8Array(analyser.fftSize);let last=0;const tick=()=>{if(!listening)return;analyser.getByteTimeDomainData(data);let energy=0;for(const v of data)energy+=(v-128)**2;const rms=Math.sqrt(energy/data.length);if(rms>7&&Date.now()-last>800){last=Date.now();armSilence();}voiceRAF=requestAnimationFrame(tick);};tick();}catch{/* Recognition still works; speech events reset the silence timer. */}}
function releaseMic(){clearInterval(voiceTick);clearTimeout(silenceTimer);cancelAnimationFrame(voiceRAF);voiceStream?.getTracks().forEach(t=>t.stop());voiceStream=null;if(voiceAudio){voiceAudio.close().catch(()=>{});voiceAudio=null;}recognition?.stop();recognition=null;mic=false;}
openVoice=function(id=''){if(listening)return;activeDraft='';voiceContext=id||detailID||'';voiceOpen=true;voiceManual=false;record();};
record=function(){if(listening){finishListening();return;}const SR=window.SpeechRecognition||window.webkitSpeechRecognition;voiceOpen=true;voiceError=false;if(!SR){voiceError=true;mountVoice();return;}listening=true;mic=true;voiceElapsed=0;voiceBase=voiceText;armSilence();voiceTick=setInterval(()=>{voiceElapsed++;const el=document.getElementById('voice-elapsed');if(el)el.textContent=Math.floor(voiceElapsed/60)+':'+String(voiceElapsed%60).padStart(2,'0');},1000);recognition=new SR();recognition.lang='zh-CN';recognition.continuous=true;recognition.interimResults=true;recognition.onspeechstart=armSilence;recognition.onresult=e=>{armSilence();let txt='';for(let i=0;i<e.results.length;i++)txt+=e.results[i][0].transcript;voiceText=voiceBase+txt;};recognition.onerror=e=>{if(e.error==='no-speech')return;voiceError=true;listening=false;releaseMic();mountVoice();toast('当前浏览器未能使用语音，可选择键盘或体验示例。');};recognition.onend=()=>{if(listening&&recognition){voiceBase=voiceText;try{recognition.start();}catch{finishListening();}}};try{recognition.start();monitorSilence();}catch{listening=false;releaseMic();voiceError=true;}mountVoice();};
mountVoice=function(){const n=S.drafts?.length||0;document.querySelector('.app').style.setProperty('--voice-bottom',S.page==='home'?'155px':'88px');document.getElementById('floating').innerHTML=`${n?`<button class="draft-fab" onclick="showDrafts()" aria-label="打开 ${n} 批暂存指示">${icon('draft')}<b>${n}</b></button>`:''}${voiceOpen?`<div class="handsfree-bar" role="region" aria-label="全局语音控制">${listening?`<span class="sound-bars"><i></i><i></i><i></i></span><span class="listening-copy">正在听 <small id="voice-elapsed">${Math.floor(voiceElapsed/60)}:${String(voiceElapsed%60).padStart(2,'0')}</small></span><button class="finish-record" onclick="finishListening()">说完了</button>`:`<span class="listening-copy">${voiceError?'语音暂不可用':'随时交代'}</span><button onclick="record()">重试</button>`}<button onclick="manualVoice()" aria-label="打开手动输入">键盘</button><button onclick="voiceExample()" aria-label="体验语音示例">示例</button><button onclick="closeVoice()" aria-label="收起语音">×</button></div>`:`<button class="floating-voice" onclick="openVoice()" aria-label="点击开始语音，再点结束，无需长按">${icon('mic')}</button>`}`;};
function finishListening(){if(!voiceOpen)return;listening=false;releaseMic();voiceOpen=false;mountVoice();if(voiceText.trim())reviewVoice();else toast('没有识别到内容，录音已关闭。');}
closeVoice=function(){if(listening&&voiceText.trim()){finishListening();return;}listening=false;releaseMic();voiceOpen=false;mountVoice();};
function manualVoice(){listening=false;releaseMic();voiceOpen=false;mountVoice();sheet('手动补充',`<p class="small muted">一行一件事，整理后再由您确认。</p><textarea class="inputbox" id="manual-voice" placeholder="例如：牛奶照旧；餐厅先别订">${esc(voiceText)}</textarea><button class="primary wide" onclick="voiceText=document.getElementById('manual-voice').value;reviewVoice()">整理一下</button>`);}
function voiceExample(){listening=false;releaseMic();voiceOpen=false;voiceContext='';voiceText='牛奶照旧，蔬菜减半；接奶奶的餐厅先别订；继续关注蒸烤箱优惠；帮我整理周末带娃行李清单';mountVoice();reviewVoice();}
function reviewVoice(){voiceRows=prepareRows(voiceText);if(!voiceRows.length)return toast('请先补充一句。');sheet('我整理好了，您过一遍',`<p class="small muted">共 ${voiceRows.length} 条指示 · 尚未发送。可修改，确认后暂存或交给主会话。</p><div class="review-rows">${voiceRows.map((r,i)=>`<label><span>${i+1}</span><textarea aria-label="第 ${i+1} 条指示" oninput="voiceRows[${i}].text=this.value">${esc(r.text)}</textarea></label>`).join('')}</div><details class="voice-original"><summary>查看识别原文</summary><p>${esc(voiceText)}</p></details><div class="review-actions"><button class="secondary" onclick="saveVoiceDraft()">确认，暂存</button><button class="primary" onclick="dispatchVoice()">确认，发给主会话</button></div><p class="notice">暂存不会启动任务；发送后由总助理继续处理。</p>`);}
function saveVoiceDraft(){const rows=voiceRows.filter(r=>r.text.trim());if(!rows.length)return toast('没有可暂存的指示。');const d={id:activeDraft||'draft_'+Date.now(),rows:JSON.parse(JSON.stringify(rows)),at:now().toISOString(),original:voiceText};S.drafts=S.drafts.filter(x=>x.id!==d.id);S.drafts.push(d);activeDraft='';voiceText='';save();closeModal();mountVoice();toast('已暂存，右侧便笺随时查看。');}
function dispatchVoice(){const text=voiceRows.map(r=>r.text.trim()).filter(Boolean).join('；');if(!text)return;const context=voiceRows[0]?.context||'';processInput(text,context);const sent=S.messages.at(-1);if(sent?.kind==='batch_v7')sent.input='查看进展后，我的安排：'+text;if(activeDraft)S.drafts=S.drafts.filter(d=>d.id!==activeDraft);activeDraft='';voiceText='';voiceRows=[];save();closeModal();go('home');document.getElementById('main').scrollTop=999999;}
function showDrafts(){sheet('暂存的交代',`<p class="small muted">这些指示还没有发送，也没有启动任务。</p>${S.drafts.length?S.drafts.map(d=>`<div class="draft-entry"><small>${fmt(d.at)} · ${d.rows.length} 条</small><p>${d.rows.map(r=>esc(r.text)).join('<br>')}</p><button class="secondary" onclick="editDraft('${d.id}')">过一遍，再发送</button><button onclick="deleteDraft('${d.id}')">删除</button></div>`).join(''):'<p class="muted">暂无暂存内容。</p>'}`);}
function editDraft(id){const d=S.drafts.find(x=>x.id===id);if(!d)return;activeDraft=id;voiceText=d.rows.map(r=>r.text).join('；');voiceContext=d.rows[0]?.context||'';reviewVoice();}
function deleteDraft(id){S.drafts=S.drafts.filter(d=>d.id!==id);save();showDrafts();mountVoice();}
// Keep unresolved payment handoffs visible until acknowledged.
const oldAnswer=answerConfirmation;
answerConfirmation=function(id,qid,i){if(qid==='care_info'){if(i===0){voiceContext=id;activeDraft='';voiceText='';manualVoice();}else pause(id);return;}oldAnswer(id,qid,i);};
const oldArchive=pending;
pending=function(){return oldArchive().filter(t=>!needUser(t));};
const priorDetail=detail;
detail=function(id){priorDetail(id);const t=entity(id);if(!t)return;const controls=document.querySelector('.taskmore .control-row');if(controls)controls.insertAdjacentHTML('beforeend',`<button onclick="editStart('${id}')">启动时间</button>`);};
function editStart(id){const t=entity(id),v=startAt(t);sheet('启动时间',`<p class="small muted">记录实际或预计启动时间，独立于需用时间。</p><input class="modal-input" id="start-input" type="datetime-local" value="${v?new Date(ts(v)+28800000).toISOString().slice(0,16):''}"><button class="primary wide" onclick="saveStart('${id}')">保存</button>`);}
function saveStart(id){const t=entity(id),v=document.getElementById('start-input').value||null;if(t.status==='todo')t.scheduledStart=v;else t.startedAt=v;if(!v){t.startedAt=null;t.scheduledStart=null;}save();render();detail(id);}
initOverview();save();render();

const priorSettings=settings;
settings=function(){priorSettings();const panel=document.querySelector('.sheet');if(panel)panel.insertAdjacentHTML('beforeend','<a class="pdf-open" href="assets/xiaotian-source-v29.zip" download="xiaotian-source-v29.zip">下载最新版项目源码 ZIP ↓</a>');};
